namespace sv_60d15ffaf1824d54abde212bf5d89901.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse.
/// Each user circuit gets its own instance, so one manager switching
/// warehouses never affects another.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public string CurrentWarehouseId { get; private set; } = AvailableWarehouses[0].Id;
    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == CurrentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (CurrentWarehouseId == warehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_60d15ffaf1824d54abde212bf5d89901.Services;

/// <summary>
/// Simulates a database query for low-stock items in a warehouse.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database call with a random result.
        return Task.FromResult(_random.Next(0, 16));
    }
}

namespace sv_60d15ffaf1824d54abde212bf5d89901.Services;

/// <summary>
/// Scoped service that holds the latest low-stock alert count and
/// provides a polling mechanism. Components subscribe to OnChange
/// to react when new data arrives. Polling is ref-counted so the
/// dashboard can start/stop it while the sidebar badge simply reads
/// the latest value.
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;

    private CancellationTokenSource? _cts;
    private int _pollingRefCount;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public InventoryAlertState(
        InventoryAlertService alertService,
        WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Begins polling every 10 seconds. Safe to call multiple times;
    /// polling runs as long as at least one caller has started it.
    /// </summary>
    public void StartPolling()
    {
        _pollingRefCount++;
        if (_pollingRefCount == 1)
        {
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Decrements the polling ref count. Stops polling when no
    /// callers remain.
    /// </summary>
    public void StopPolling()
    {
        _pollingRefCount = Math.Max(0, _pollingRefCount - 1);
        if (_pollingRefCount == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start, then every 10 seconds.
        await FetchAsync();

        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await timer.WaitForNextTickAsync(ct))
                    break;
                await FetchAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAsync()
    {
        var count = await _alertService.GetLowStockCountAsync(
            _warehouseState.CurrentWarehouseId);
        LowStockCount = count;
        OnChange?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // When the warehouse changes, fetch fresh data immediately.
        if (_cts is { IsCancellationRequested: false })
        {
            await FetchAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

